class Solution {
public:
    vector<int> countRectangles(vector<vector<int>>& rectangles, vector<vector<int>>& points) {
        vector<vector<int>> by_h(101);
        for (const auto& r : rectangles) {
            by_h[r[1]].push_back(r[0]);
        }
        for (int h = 1; h <= 100; h++) {
            sort(by_h[h].begin(), by_h[h].end());
        }
        vector<int> ans;
        for (const auto& p : points) {
            int px = p[0], py = p[1];
            int cnt = 0;
            for (int h = py; h <= 100; h++) {
                const auto& bucket = by_h[h];
                auto it = lower_bound(bucket.begin(), bucket.end(), px);
                cnt += bucket.end() - it;
            }
            ans.push_back(cnt);
        }
        return ans;
    }
};

class Solution {
    public int[] countRectangles(int[][] rectangles, int[][] points) {
        List<List<Integer>> by_h = new ArrayList<>();
        for (int i = 0; i <= 100; i++) by_h.add(new ArrayList<>());
        for (int[] r : rectangles) {
            by_h.get(r[1]).add(r[0]);
        }
        for (int h = 1; h <= 100; h++) {
            Collections.sort(by_h.get(h));
        }
        int[] ans = new int[points.length];
        for (int i = 0; i < points.length; i++) {
            int px = points[i][0], py = points[i][1];
            int cnt = 0;
            for (int h = py; h <= 100; h++) {
                List<Integer> bucket = by_h.get(h);
                int l = 0, r = bucket.size();
                while (l < r) {
                    int mid = (l + r) / 2;
                    if (bucket.get(mid) >= px) r = mid;
                    else l = mid + 1;
                }
                cnt += bucket.size() - l;
            }
            ans[i] = cnt;
        }
        return ans;
    }
}

