var countRectangles = function(rectangles, points) {
    const by_h = Array.from({ length: 101 }, () => []);
    for (const [l, h] of rectangles) {
        by_h[h].push(l);
    }
    for (let h = 1; h <= 100; h++) {
        by_h[h].sort((a, b) => a - b);
    }
    const ans = [];
    for (const [px, py] of points) {
        let cnt = 0;
        for (let h = py; h <= 100; h++) {
            const bucket = by_h[h];
            let l = 0, r = bucket.length;
            while (l < r) {
                const mid = (l + r) >> 1;
                if (bucket[mid] >= px) r = mid;
                else l = mid + 1;
            }
            cnt += bucket.length - l;
        }
        ans.push(cnt);
    }
    return ans;
};
